/* ==== INTERFACE ====
方向：杂志编辑风（Editorial）。采用典雅从容的人文社科刊物排版语言，衬线大标题与高可读性正文字体混排；辅以精细规则线、章节眉首（Header/Kicker）、精微引语栏与双栏对比论证，呈现韦伯理论概念链条与局限分析的思辨性。
reference style:03-editorial
token --bg：页面基底色 #f8f6f1（温润的书卷纸本色）。
token --text：正文主要深色 #22201e（温暖沉稳的炭墨色）。
token --font-serif：标题与文眼衬线字体栈 "NTF-source-serif-4", "NTF-noto-serif-sc", serif。
token --font-sans：说明、标签、图表、数字与控件无衬线字体栈 "NTF-inter", "NTF-noto-sans-sc", sans-serif。
token --fs-h1：普通页题名字号 44px / 行高 1.25。
token --fs-h2：区块二级标题字号 28px / 行高 1.35。
token --fs-lead：导言或文眼字号 22px / 行高 1.55。
token --fs-body：正文字号 17px / 行高 1.65。
token --fs-label：图注、元信息、章节标眉 13px / 行高 1.4。
class .nt-title：普通页主标题，使用衬线字栈，默认 44px/1.25，字重 600；封面强调可通过 .nt-title-cover 或 .is-cover 放大至 64px。
class .nt-subtitle：副标题或章节引文，衬线或无衬线配比，22px/1.55，轻量沉着。
class .nt-kicker：章节栏目、眉题微标（如“理论溯源 / 核心论点”），无衬线全大写或等宽跟踪字距，13px，字重 600。
class .nt-rule：细黑精细分隔线（0.75px 或 1px border-top），提供经典报刊横跨感。
class .nt-quote：文眼摘录/引言块，左侧精致墨线或上下精线，衬线斜体，留白充裕。
class .nt-caption：图注/文献说明，无衬线 13px，次要墨色。
class .nt-concept-chain：逻辑链条节点卡片容器，清晰边界、无多余厚重浮雕。
class .nt-controls：页面交互按钮、筛选器组，采用细描边极简圆角或方角，点击与激活状态明确。
默认：不设 data-variant；无图时保持纯净纸感与精巧排印层级。
variant opening：开篇封面态，居中或经典大开本不对称排布，标题增强。
==== /INTERFACE ==== */

/* --------------------------------------------------------------------------
   1. 字体声明
   -------------------------------------------------------------------------- */
@font-face {
  font-family: "NTF-noto-serif-sc";
  src: url("fonts/library/noto-serif-sc/face-0.ttf");
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-source-serif-4";
  src: url("fonts/library/source-serif-4/face-0.ttf");
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-source-serif-4";
  src: url("fonts/library/source-serif-4/face-1.ttf");
  font-weight: 200 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

/* --------------------------------------------------------------------------
   2. 根变量：色彩、排印系统与空间
   -------------------------------------------------------------------------- */
:root {
  /* 基础纸质与炭墨色彩 */
  --bg: #f8f6f1;
  --bg-subtle: #f1ede4;
  --text: #201e1c;
  --text-secondary: #57524d;
  --text-muted: #7d7770;

  /* 编辑风格点缀：古典印泥砖红、墨水深蓝、暗金棕 */
  --accent: #9b382c;           /* 沉稳砖红，用于重点概念与对比断言 */
  --accent-muted: #d9cec1;     /* 浅陶土衬底 */
  --accent-blue: #23435c;      /* 概念因果对比辅助色 */
  --accent-gold: #8c6d3b;      /* 韦伯文本引述色 */

  --border-light: #dfd9ce;
  --border-dark: #201e1c;
  --focus: #9b382c;

  /* 字体族 */
  --font-serif: "NTF-source-serif-4", "NTF-noto-serif-sc", "Songti SC", serif;
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;

  /* 杂志字阶定义 (1600x900 逻辑画布) */
  --fs-cover: 60px;
  --fs-h1: 42px;
  --fs-h2: 28px;
  --fs-h3: 22px;
  --fs-lead: 20px;
  --fs-body: 17px;
  --fs-caption: 14px;
  --fs-label: 12px;

  /* 行高 */
  --lh-tight: 1.2;
  --lh-heading: 1.28;
  --lh-lead: 1.5;
  --lh-body: 1.68;
  --lh-caption: 1.4;

  /* 间距刻度 */
  --space-xs: 8px;
  --space-sm: 16px;
  --space-md: 24px;
  --space-lg: 40px;
  --space-xl: 64px;
}

/* --------------------------------------------------------------------------
   3. 舞台与变体
   -------------------------------------------------------------------------- */
#stage {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: var(--lh-body);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  /* 细腻的书页质感微光与极轻印刷网点 */
  background-image:
    radial-gradient(ellipse at 88% 12%, rgba(217, 206, 193, 0.35) 0%, transparent 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.4) 0%, rgba(248, 246, 241, 1) 100%);
}

/* 杂志开篇封面变体 */
html[data-variant="opening"] #stage {
  background-color: #f5f2eb;
  background-image:
    radial-gradient(circle at 15% 85%, rgba(155, 56, 44, 0.05) 0%, transparent 40%),
    linear-gradient(180deg, #fbf9f5 0%, #f1ede3 100%);
}

/* 深度对比 / 批判反思变体：局限性剖析 */
html[data-variant="critique"] #stage {
  background-color: #f4efe6;
  background-image:
    linear-gradient(90deg, rgba(35, 67, 92, 0.03) 0%, transparent 60%);
}

/* --------------------------------------------------------------------------
   4. 排版核心类 (Editorial Typographic Elements)
   -------------------------------------------------------------------------- */

/* 栏目微标 / 刊头小字 */
.nt-kicker {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: var(--space-xs);
}

.nt-kicker::after {
  content: "";
  display: inline-block;
  width: 24px;
  height: 1px;
  background-color: var(--accent);
}

/* 页面主标题 */
.nt-title {
  font-family: var(--font-serif);
  font-size: var(--fs-h1);
  font-weight: 600;
  line-height: var(--lh-heading);
  color: var(--text);
  margin: 0 0 var(--space-sm) 0;
  letter-spacing: -0.01em;
}

.nt-title:lang(zh),
:lang(zh) > .nt-title {
  font-weight: 600;
  letter-spacing: 0.02em;
}

/* 封面特大标题 */
.nt-title-cover {
  font-family: var(--font-serif);
  font-size: var(--fs-cover);
  font-weight: 600;
  line-height: var(--lh-tight);
  color: var(--text);
  letter-spacing: -0.015em;
  margin: 0 0 var(--space-md) 0;
}

/* 区块二级标题 */
.nt-section-title {
  font-family: var(--font-serif);
  font-size: var(--fs-h2);
  font-weight: 600;
  line-height: var(--lh-heading);
  color: var(--text);
  margin: 0 0 var(--space-xs) 0;
}

/* 副标题 / 提要说明 */
.nt-lead {
  font-family: var(--font-serif);
  font-size: var(--fs-lead);
  line-height: var(--lh-lead);
  color: var(--text-secondary);
  margin: 0 0 var(--space-md) 0;
}

/* 正文段落 */
.nt-paragraph {
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: var(--lh-body);
  color: var(--text);
  margin-bottom: var(--space-sm);
}

/* 杂志首字下沉 (Drop cap) */
.nt-dropcap::first-letter {
  font-family: var(--font-serif);
  font-size: 3.4em;
  float: left;
  line-height: 0.82;
  padding-right: 12px;
  padding-top: 4px;
  color: var(--accent);
  font-weight: 600;
}

/* 报刊式经典规则横线 */
.nt-rule {
  border: 0;
  border-top: 1px solid var(--border-light);
  margin: var(--space-md) 0;
  width: 100%;
}

.nt-rule-dark {
  border-top: 1px solid var(--border-dark);
}

.nt-rule-accent {
  border-top: 2px solid var(--accent);
}

/* 经典文献摘录 / 韦伯原著文眼 */
.nt-quote {
  font-family: var(--font-serif);
  font-size: 20px;
  font-style: italic;
  line-height: 1.6;
  color: var(--text);
  padding: var(--space-sm) 0 var(--space-sm) var(--space-md);
  border-left: 3px solid var(--accent);
  margin: var(--space-md) 0;
  background: rgba(241, 237, 228, 0.4);
}

.nt-quote-source {
  display: block;
  font-family: var(--font-sans);
  font-size: var(--fs-caption);
  font-style: normal;
  color: var(--text-muted);
  margin-top: var(--space-xs);
  letter-spacing: 0.04em;
}

/* 图注与学术文献边注 */
.nt-caption {
  font-family: var(--font-sans);
  font-size: var(--fs-caption);
  line-height: var(--lh-caption);
  color: var(--text-secondary);
  border-top: 1px solid var(--border-light);
  padding-top: 6px;
  margin-top: 8px;
}

/* --------------------------------------------------------------------------
   5. 杂志式内容模块与比较排版 (Editorial Panels & Contrast)
   -------------------------------------------------------------------------- */

/* 分栏/文献块：纯净边界，杜绝浮夸卡片墙 */
.nt-column {
  position: relative;
  display: flex;
  flex-direction: column;
}

.nt-column-bordered {
  padding: 0 var(--space-md);
  border-left: 1px solid var(--border-light);
}

.nt-column-bordered:first-child {
  padding-left: 0;
  border-left: none;
}

/* 论点逻辑链条步进项 (天职观 -> 现世禁欲 -> 资本积累) */
.nt-chain-step {
  padding: var(--space-sm) var(--space-md);
  background: #ffffff;
  border: 1px solid var(--border-light);
  border-top: 3px solid var(--border-dark);
  margin-bottom: var(--space-sm);
  box-shadow: 0 2px 4px rgba(32, 30, 28, 0.03);
  transition: border-color 0.2s ease;
}

.nt-chain-step.is-active,
.nt-chain-step:hover {
  border-top-color: var(--accent);
}

.nt-chain-step .nt-step-num {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.08em;
  margin-bottom: 4px;
}

/* 辨析双重视角（如：单一因果论 VS 亲和性关联论） */
.nt-versus-card {
  background: #ffffff;
  border: 1px solid var(--border-light);
  padding: var(--space-md);
  box-sizing: border-box;
  height: 100%;
}

.nt-versus-card.type-flawed {
  border-top: 3px solid var(--text-muted);
}

.nt-versus-card.type-accurate {
  border-top: 3px solid var(--accent);
  background: #faf8f5;
}

/* --------------------------------------------------------------------------
   6. 交互控件与操作状态 (Controls & Interactive States)
   -------------------------------------------------------------------------- */

.nt-controls {
  display: inline-flex;
  gap: 12px;
  align-items: center;
}

.nt-button {
  font-family: var(--font-sans);
  font-size: var(--fs-caption);
  font-weight: 500;
  color: var(--text);
  background: #ffffff;
  border: 1px solid var(--border-light);
  padding: 8px 18px;
  cursor: pointer;
  border-radius: 0; /* 杂志风保持干练方角或微圆角 */
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  outline: none;
}

.nt-button:hover {
  background: var(--bg-subtle);
  border-color: var(--text-muted);
}

.nt-button:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.nt-button[aria-pressed="true"],
.nt-button.is-active {
  background: var(--text);
  color: #ffffff;
  border-color: var(--text);
}

/* 语义徽标 / 标签 */
.nt-tag {
  display: inline-block;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
  padding: 3px 8px;
  background: var(--bg-subtle);
  color: var(--text-secondary);
  border: 1px solid var(--border-light);
  letter-spacing: 0.04em;
}

.nt-tag-accent {
  background: rgba(155, 56, 44, 0.08);
  color: var(--accent);
  border-color: rgba(155, 56, 44, 0.25);
}

/* --------------------------------------------------------------------------
   7. 图表与 SVG 关系图规范
   -------------------------------------------------------------------------- */
svg text {
  font-family: var(--font-sans);
}

/* 关系线与因果图示 */
.nt-diagram-line {
  stroke: var(--border-light);
  stroke-width: 1.5;
  fill: none;
}

.nt-diagram-line-active {
  stroke: var(--accent);
  stroke-width: 2;
  fill: none;
}

.nt-diagram-node {
  fill: #ffffff;
  stroke: var(--text);
  stroke-width: 1.5;
}

.nt-diagram-node-accent {
  fill: var(--accent);
  stroke: var(--accent);
}
